import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("transfer undo", () => {
  test("transfer undo", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-t`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.transfer(pg_vic, p_ada, `${sheet}-t`)).toBe(true);
    expect(await ui.transfer(pg_vic, p_ben, `${sheet}-t`)).toBe(true);
    await ui.loadSheet(pg_vic, `${sheet}-t`);
    const p_ada_2 = await ui.personId(pg_vic, "Ada");
    const c_ada_0_2 = await ui.claimAt(pg_vic, p_ada_2, 0);
    const p_ben_2 = await ui.personId(pg_vic, "Ben");
    expect(await ui.transferUndo(pg_vic, p_ada_2)).toBe(true);
    await ui.refresh(pg_uma);
    await ui.loadSheet(pg_uma, `${sheet}-t`);
    expect(await ui.transferUndo(pg_uma, p_ben_2)).toBe(false);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    await ui.loadSheet(pg_wes, `${sheet}-t`);
    await ui.setToday(pg_wes, "2026-03-11");
    expect(await ui.transferUndo(pg_wes, p_ben_2)).toBe(false);
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("person-row-" + p_ben_2).getByTestId("person-name")).toHaveText("Ben");
    await expect(pg_wes.getByTestId("person-row-" + p_ben_2).getByTestId("person-origin")).toHaveText(`${sheet}`);
    await expect(pg_wes.getByTestId("person-row-" + p_ben_2).getByTestId("person-statement-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-open-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_wes.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await ui.expectAudit(`${sheet}-t`, [
      `RATE_SET sheet=${sheet}-t by=uma grade=A rate=20.00`,
      `ROLE_SET sheet=${sheet}-t by=uma user=vic role=steward`,
      `ROLE_SET sheet=${sheet}-t by=uma user=wes role=steward`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=Ada from=${sheet}`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=10.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=10.00 due-total=1.00 overdue-total=0.00`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=Ben from=${sheet}`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ben claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=Ada to=${sheet}`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_TRANSFER_UNDONE sheet=${sheet}-t by=vic name=Ada to=${sheet}`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=0.00 due-total=0.00 overdue-total=0.00`,
      `SNAPSHOT sheet=${sheet}-t by=wes name=Ben due-total=n/a`
    ]);
    await ui.loadSheet(pg_wes, sheet);
    const p_ada_3 = await ui.personId(pg_wes, "Ada");
    const c_ada_0_3 = await ui.claimAt(pg_wes, p_ada_3, 0);
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("person-row-" + p_ada_3).getByTestId("person-name")).toHaveText("Ada");
    await expect(pg_wes.getByTestId("person-row-" + p_ada_3).getByTestId("person-origin")).toHaveText(`${sheet}-t`);
    await expect(pg_wes.getByTestId("person-row-" + p_ada_3).getByTestId("person-statement-count")).toHaveText("1");
    await expect(pg_wes.getByTestId("claim-row-" + c_ada_0_3).getByTestId("claim-number")).toHaveText("FY2026-2");
    await expect(pg_wes.getByTestId("claim-row-" + c_ada_0_3).getByTestId("claim-status")).toHaveText("OPEN");
    await expect(pg_wes.getByTestId("claim-row-" + c_ada_0_3).getByTestId("claim-stated")).toHaveText("yes");
    await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("10.00");
    await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("1.00");
    await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-open-total")).toHaveText("1.00");
